from pathlib import Path
from docx import Document
from docx.enum.text import WD_COLOR_INDEX
from copy import deepcopy
import sys
ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/'additional_instr/printable'; OUT.mkdir(parents=True,exist_ok=True)
T=ROOT/'Инструкции_ОТ/ИОТ-СПС-10.docx'
HEAD=['ОБЩИЕ ТРЕБОВАНИЯ ОХРАНЫ ТРУДА','ТРЕБОВАНИЯ ОХРАНЫ ТРУДА ПЕРЕД НАЧАЛОМ РАБОТЫ','ТРЕБОВАНИЯ ОХРАНЫ ТРУДА ВО ВРЕМЯ РАБОТЫ','ТРЕБОВАНИЯ ОХРАНЫ ТРУДА В АВАРИЙНЫХ СИТУАЦИЯХ','ТРЕБОВАНИЯ ОХРАНЫ ТРУДА ПО ОКОНЧАНИИ РАБОТЫ']

def put_before(d,anchor,text,style=None,yellow=False):
 p=d.add_paragraph(style=style); anchor.addprevious(p._p); r=p.add_run(text)
 if yellow:r.font.highlight_color=WD_COLOR_INDEX.YELLOW
 return p

def build(code,title,sections,question):
 d=Document(T); body=d.element.body; els=list(body); anchor=els[9]
 # preserve title page, create content before old body, then remove old body through appendix; preserve acquaintance sheet
 old=list(body); last_table=[x for x in old if x.tag.endswith('}tbl')][-1]
 # retain from acquaintance sheet heading through last table; find heading by text
 sheet=next(x for x in old if 'ЛИСТ ОЗНАКОМЛЕНИЯ' in ''.join(x.xpath('.//w:t/text()')).upper())
 si=old.index(sheet)
 for e in old[9:si]: body.remove(e)
 # make new content before sheet
 p=d.paragraphs[4]; p.clear(); p.add_run('Инструкция по охране труда '+title)
 p=d.paragraphs[5]; p.clear(); p.add_run(code+' (проект)'); p.runs[0].font.highlight_color=WD_COLOR_INDEX.YELLOW
 for n,items in enumerate(sections,1):
  h=put_before(d,sheet,f'{n}. {HEAD[n-1]}','Heading 1'); h.paragraph_format.page_break_before=(n==1)
  for j,s in enumerate(items,1): put_before(d,sheet,f'{n}.{j}. {s}')
  if n==1: put_before(d,sheet,'Вопрос для согласования: '+question,yellow=True)
 h=put_before(d,sheet,'Приложение 1','Heading 1'); h.paragraph_format.page_break_before=True
 put_before(d,sheet,'Документы, подлежащие проверке при согласовании инструкции')
 for s in ['Трудовой кодекс Российской Федерации; действующие обязательные требования охраны труда, применимые к порученным работам.', 'Материалы СОУТ и оценки профессиональных рисков, локальные нормы выдачи СИЗ, планы эвакуации и инструкции организации.', 'Документация изготовителей применяемого оборудования и паспорта безопасности используемых средств.']:
  put_before(d,sheet,s)
 put_before(d,sheet,'Уточнить применимые нормативные акты, их действующие редакции и локальные документы на дату утверждения.',yellow=True)
 # neutralize sample's claimed review and approval metadata; fill title details with neutral placeholders
 t=d.tables[1]
 for row in t.rows:
  if len(row.cells)>1 and ('Разработана на' in row.cells[0].text or 'Пересмотр' in row.cells[0].text): row.cells[1].text='________________________________________'
 out=OUT/(code+'.docx'); d.save(out)
 # reopen to validate
 d=Document(out); assert len(d.tables)==3 and len(d.paragraphs)>15 and all(any(p.text.startswith(str(i)+'. '+HEAD[i-1]) for p in d.paragraphs) for i in range(1,6))
 print(out.name,len(d.paragraphs))

common1=['К самостоятельной работе допускается работник после обязательных для выполняемой работы инструктажей, обучения и проверки знаний, а также медицинских осмотров и иных процедур допуска в случаях, установленных законодательством и работодателем.', 'Работник выполняет только порученную работу в пределах подготовки и допуска, соблюдает правила внутреннего распорядка, пожарной безопасности и инструкции по используемому оборудованию. Опасную работу без установленного допуска выполнять запрещено.', 'Использовать исправные средства индивидуальной защиты, предусмотренные локальными нормами и характером задания; при отсутствии необходимых СИЗ к работе не приступать.', 'При обнаружении опасности, неисправности или ухудшении самочувствия прекратить работу, предупредить окружающих и сообщить непосредственному руководителю.']
common2=['Получить задание, уточнить место, порядок работ, взаимодействие с другими работниками и безопасные маршруты.', 'Осмотреть рабочее место и проходы: обеспечить освещение, устойчивость покрытий и отсутствие препятствий; проверить доступность выходов и средств связи.', 'Проверить исправность используемых средств и наличие необходимых СИЗ. Неисправное оборудование вывести из применения и сообщить руководителю.']
common4=['При непосредственной угрозе жизни или здоровью остановить работу, по возможности безопасно отключить оборудование, предупредить людей, отойти в безопасное место и сообщить руководителю.', 'При пожаре сообщить по номеру 112 или 101, назвать место и характер происшествия, организованно эвакуироваться; использовать первичные средства пожаротушения только при обученности и отсутствии угрозы.', 'При травме вызвать скорую помощь по номеру 112 или 103, сообщить руководителю; оказать первую помощь в пределах подготовки, не подвергая себя опасности. Сохранить обстановку происшествия, если это безопасно.', 'При поражении электрическим током сначала безопасно прекратить воздействие тока, не касаясь пострадавшего до отключения; вызвать помощь и оказать первую помощь в пределах подготовки.']
common5=['Остановить оборудование, отключить питание в установленном порядке, убрать используемые средства в отведённое место; не выполнять не порученные ремонтные работы.', 'Привести рабочее место в безопасное состояние, убрать отходы в предназначенные места, не загромождать проходы и выходы.', 'Сообщить руководителю о неисправностях, происшествиях и неустранённых опасностях; снять и убрать СИЗ, вымыть руки.']
clean1=['Работы включают ручную сухую и влажную уборку, применение разрешённых чистящих средств и уборочной техники по поручению; санитарные, служебные и технические помещения убираются в установленных границах.', 'Опасности: скользкие поверхности, контакт с химическими веществами, электрический ток, вращающиеся части машин, аэрозоли, физическая нагрузка, движение посетителей.']
clean2=['Проверить целостность инвентаря, исправность кабеля, вилки и корпуса машины; убедиться, что химические средства промаркированы, а сведения по их безопасному применению доступны.', 'Определить и обозначить зону уборки, предупредить посетителей, установить знаки «Осторожно, мокрый пол»; не перекрывать эвакуационные выходы.']
clean3=['Убирать последовательно, избегая скопления воды; использовать раздельный промаркированный инвентарь по зонам. Не собирать руками острые или неизвестные предметы: оградить место и сообщить руководителю.', 'Использовать средство только по маркировке и инструкции изготовителя, соблюдать указанную концентрацию, вентиляцию и требования к СИЗ. Не смешивать разные средства и не переливать в пищевую тару.', 'Работать на исправной машине после обучения; следить за кабелем и окружающими. Не касаться электрических соединений мокрыми руками, не допускать попадания воды на электрические части.', 'Перед чисткой, сменой оснастки и устранением засора остановить машину и отключить её от источника энергии. Дождаться полной остановки вращающихся частей.', 'Не поднимать и не переносить груз рывком или при недостаточной видимости; применять тележки и помощь другого работника. Работу с лестниц выполнять только при наличии допуска и безопасной организации.']
clean4=['При проливе средства изолировать зону, не вдыхать пары; уборку выполнять только при подготовке и наличии подходящих СИЗ по паспорту безопасности. При неизвестном составе отойти и вызвать ответственного.', 'При попадании средства на кожу или в глаза немедленно начать промывание водой согласно паспорту безопасности, снять загрязнённую одежду и обратиться за медицинской помощью; передать сведения о средстве.']
clean5=['Отключить, очистить и просушить оборудование по инструкции изготовителя; слить растворы только в предусмотренные места. Убрать химические средства в промаркированной закрытой таре.', 'Снять загрязнённые СИЗ без контакта с кожей, направить их на очистку или замену в установленном порядке.']
roles=[('ИОТ-КЛИ-01','для уборщика производственных и служебных помещений','уборку санитарных, служебных и технических помещений'),('ИОТ-КЛИ-02','для супервайзера общественных зон','уборку общественных зон и контроль работников'),('ИОТ-КЛИ-04','для оператора по уборке','ручную и машинную уборку помещений'),('ИОТ-КЛИ-05','для супервайзера общественных зон и служебных помещений','уборку общественных зон и служебных помещений и контроль работников'),('ИОТ-КЛИ-06','для супервайзера службы клининга','уборку и контроль работников службы клининга')]

def batch1():
 for code,title,scope in roles:
  supervisor='супервайзера' in title
  extra=['При распределении работ проверять подготовку и наличие СИЗ у работников, согласовать ограждение зон и остановить работы при выявлении опасности. Не подменять специальные допуски организационным контролем.'] if supervisor else []
  build(code,title,[[f'Инструкция устанавливает требования при выполнении работника по заданию работодателя: {scope}.']+clean1+common1,common2+clean2,clean3+extra,common4+clean4,common5+clean5], 'Уточнить границы убираемых зон, модели техники, перечень средств, локальные нормы СИЗ и применимость работ на лестницах.')
 build('ИОТ-КЛИ-03','для начальника службы клининга',[[ 'Работник организует и контролирует уборочные работы; личная работа с уборочной техникой и химическими средствами настоящей инструкцией не предусматривается.','Основные опасности: падение на мокром полу, движение техники и посетителей, контакт с опасной зоной, электрический ток, напряжённость труда.']+common1,common2+['Уточнить состав работ, выделение зон, наличие допусков, исправных средств и СИЗ у исполнителей.'],['Организовывать безопасное выполнение работ, проверять наличие инструктажей и ограждений. При выявлении угрозы остановить работы и организовать устранение причин.','При обходе не входить в ограждённую зону без согласования с исполнителем; не прикасаться к оборудованию и химическим средствам.','Передавать неисправное оборудование для ремонта уполномоченным лицам; не допускать работу без обучения и необходимой защиты.'],common4,common5], 'Уточнить границы ответственности, порядок остановки работ и маршрут обхода.')
 # convert the existing full operation and street-sweeper drafts from markdown
 mapping=[('ROLE-SPS-13_street-sweeper.md','ИОТ-СПС-13','для дворника'),('WORK-KLI-CHEM-01_cleaning-chemicals.md','ИОТ-ВИД-17','при работе с чистящими и дезинфицирующими средствами'),('WORK-KLI-MACH-01_floor-cleaning-machines.md','ИОТ-ВИД-18','при работе с уборочными электрическими машинами'),('WORK-KLI-PW-01_pressure-washer-220v.md','ИОТ-ВИД-19','при работе с мойкой высокого давления 220 В')]
 import re
 for name,code,title in mapping:
  text=(ROOT/'workbook/instructions'/name).read_text(); sections=[[] for _ in range(5)]; current=0
  for line in text.splitlines():
   if re.match(r'^## [1-5]\. ',line): current=int(line[3]); continue
   if line.startswith('## '): current=0; continue
   if not current or not line.strip() or line.startswith('###') or line.startswith('>'):continue
   s=line.strip().lstrip('- ').replace('**','').replace('`','')
   if re.search(r'пользователь|пользователя|ответ[а-я]* |проект|черновик|рабочий ID|сверить перед|подтвердить|уточнить|должны быть уточнены|локальн.{0,15}провер',s,re.I):continue
   s=re.sub(r'^\d+\.\d+\.\s*','',s)
   if s: sections[current-1].append(s)
  for n in range(5):
   if len(sections[n])<2: sections[n]+= [common1,common2,clean3,common4,common5][n]
  build(code,title,sections,'Сверить фактические операции, характеристики оборудования, паспорта средств, СИЗ и код с локальным реестром; см. перечень недоработок.')

if __name__=='__main__':
 if sys.argv[1]=='1': batch1()
